import { costs } from "./costs";

// Token Costs by epic (MVP1-E8-16, Nikhil's layout of 27 Nov 2026): one row per epic, then the
// pre-requisites and the total. Product and Engineering each have Actuals and Projected, each with
// Tokens, Build cost, Rework cost and Total; a grand total closes the row. A cell with no data shows
// "—" (the roadmap projects one figure per story, so projected tokens, build and rework are always
// "—"). Every figure comes from costs.ts, generated by `npm run costs`. Shown on wide screens only.

type Cell = { actual: { tokens: number; build: number | null; rework: number | null; total: number } | null; projected: number | null };
type Row = { key: string; name: string; product: Cell; engineering: Cell; grand: { actual: number | null; projected: number | null; total: number } };

function usd(value: number | null | undefined) {
  if (value === null || value === undefined) return "—";
  return `$${value.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

function mtok(value: number | null | undefined) {
  return value === null || value === undefined ? "—" : `${(value / 1_000_000).toFixed(1)}M`;
}

const SIDES = ["product", "engineering"] as const;
const PARTS = ["Tokens", "Build", "Rework", "Total"];

function Cells({ row }: { row: Row }) {
  return (
    <>
      {SIDES.map((side) => {
        const a = row[side].actual;
        return [
          <td key={`${side}-at`} className="grid-start">{mtok(a?.tokens)}</td>,
          <td key={`${side}-ab`}>{usd(a?.build)}</td>,
          <td key={`${side}-ar`}>{usd(a?.rework)}</td>,
          <td key={`${side}-aT`} className="grid-sum">{usd(a?.total)}</td>,
          <td key={`${side}-pt`} className="grid-start">—</td>,
          <td key={`${side}-pb`}>—</td>,
          <td key={`${side}-pr`}>—</td>,
          <td key={`${side}-pT`} className="grid-sum">{usd(row[side].projected)}</td>,
        ];
      })}
      <td className="grid-start">{usd(row.grand.actual)}</td>
      <td>{usd(row.grand.projected)}</td>
      <td className="grid-sum">{usd(row.grand.total)}</td>
    </>
  );
}

export function TokenGrid() {
  const { rows, prereq, total } = costs.split as unknown as { rows: Row[]; prereq: Row; total: Row };
  return (
    <section aria-labelledby="token-grid-title">
      <h3 className="section-subtitle" id="token-grid-title">
        By epic: Product and Engineering
      </h3>
      <p className="token-grid-narrow">Open on a laptop or desktop to see this report.</p>
      <div className="token-grid-wrap">
        <table className="token-grid">
          <thead>
            <tr>
              <th scope="col" rowSpan={3} className="grid-epic">Epic</th>
              <th scope="colgroup" colSpan={8} className="grid-start">Product</th>
              <th scope="colgroup" colSpan={8} className="grid-start">Engineering</th>
              <th scope="colgroup" colSpan={3} className="grid-start">Grand total</th>
            </tr>
            <tr>
              {SIDES.map((side) => [
                <th key={`${side}-a`} scope="colgroup" colSpan={4} className="grid-start">Actuals</th>,
                <th key={`${side}-p`} scope="colgroup" colSpan={4} className="grid-start">Projected</th>,
              ])}
              <th scope="col" rowSpan={2} className="grid-start">Actuals</th>
              <th scope="col" rowSpan={2}>Projected</th>
              <th scope="col" rowSpan={2}>Total</th>
            </tr>
            <tr>
              {[0, 1, 2, 3].map((group) =>
                PARTS.map((part, i) => (
                  <th key={`${group}-${part}`} scope="col" className={i === 0 ? "grid-start" : undefined}>
                    {part}
                  </th>
                )),
              )}
            </tr>
          </thead>
          <tbody>
            {[...rows, prereq].map((row) => (
              <tr key={row.key}>
                <th scope="row" className="grid-epic">{row.name}</th>
                <Cells row={row} />
              </tr>
            ))}
          </tbody>
          <tfoot>
            <tr>
              <th scope="row" className="grid-epic">Total</th>
              <Cells row={total} />
            </tr>
          </tfoot>
        </table>
      </div>
      <p className="note token-grid-note">
        Actuals are measured from the session record; each request counts toward Product,
        Engineering or both. Projected is the remaining stories of{" "}
        {costs.split.roadmap ? <a href={costs.split.roadmap.href}>roadmap {costs.split.roadmap.slug}</a> : "the latest roadmap"},
        on the side of each story&apos;s owner; the roadmap gives one figure per story, so its tokens,
        build and rework show —. Pre-requisites (work tied to no story) have no build or rework split,
        so a side&apos;s Total is more than its Build plus Rework.
      </p>
    </section>
  );
}
